const src = $('Vapi Eventos').first().json;
const m = src.body?.message ?? src.body ?? src.message ?? src;
const call = m.call ?? {};
const art = m.artifact ?? {};
const an = m.analysis ?? {};
const sd = an.structuredData ?? {};
const md = call.metadata ?? {};

const started = call.startedAt ?? m.startedAt ?? '';
const ended = call.endedAt ?? m.endedAt ?? '';
const dur = m.durationSeconds ?? (started && ended ? Math.round((new Date(ended) - new Date(started)) / 1000) : 0);

return [{ json: {
  call_id: String(call.id ?? m.callId ?? ''),
  lead_id: String(md.lead_id ?? ''),
  campana: String(md.campana ?? ''),
  telefono: String(call.customer?.number ?? md.telefono ?? ''),
  intentos: Number(md.intentos ?? 0),
  ended_reason: String(m.endedReason ?? call.endedReason ?? ''),
  duracion_seg: dur,
  inicio: started,
  fin: ended,
  resumen: an.summary ?? '',
  transcript: art.transcript ?? m.transcript ?? '',
  grabacion_url: art.recordingUrl ?? m.recordingUrl ?? '',
  nombre: sd.nombre ?? md.nombre ?? '',
  empresa: sd.empresa ?? md.empresa ?? '',
  sector: sd.sector ?? '',
  tamano: sd.tamano ?? '',
  problema: sd.problema ?? '',
  procesos_manuales: sd.procesos_manuales ?? '',
  quiere_automatizar: sd.quiere_automatizar ?? '',
  urgencia: sd.urgencia ?? '',
  decisor: sd.decisor,
  interes: sd.interes ?? '',
  score: sd.score,
  objecion: sd.objecion ?? '',
  resultado: sd.resultado ?? '',
  fecha_cita: sd.fecha_cita ?? '',
  email: sd.email ?? '',
  proximo_paso: sd.proximo_paso ?? ''
} }];

const cfg = $('Config').first().json;
const j = $json;
const intentos = Number(j.intentos || 0);
const ended = String(j.ended_reason || '');

let resultado = String(j.resultado || '').toLowerCase();
if (!resultado) {
  resultado = ['customer-did-not-answer', 'customer-busy', 'voicemail', 'silence-timeout'].includes(ended)
    ? 'sin_contacto'
    : 'contactado';
}

const plus = h => new Date(Date.now() + h * 3600e3).toISOString();
let estado = 'contactado';
let next = '';

switch (resultado) {
  case 'cita': estado = 'cita_agendada'; break;
  case 'humano': estado = 'humano'; break;
  case 'no_interesado': estado = 'no_interesado'; break;
  case 'callback': estado = 'reintentar'; next = plus(24); break;
  case 'info': estado = 'contactado'; next = plus(48); break;
  case 'sin_contacto':
    if (ended === 'voicemail') { estado = 'reintentar'; next = plus(24); }
    else if (intentos >= Number(cfg.max_intentos || 3)) { estado = 'nurture'; next = plus(24 * 90); }
    else { estado = 'reintentar'; next = plus(ended === 'customer-busy' ? 0.5 : 2); }
    break;
  default: estado = 'contactado'; break;
}

let score = Number(j.score || 0);
if (!score) {
  score += j.interes === 'alto' ? 40 : j.interes === 'medio' ? 25 : 10;
  score += j.urgencia === 'alta' ? 20 : j.urgencia === 'media' ? 10 : 0;
  score += j.decisor === true ? 15 : 0;
  score += j.problema ? 10 : 0;
  score += j.empresa ? 10 : 0;
  score = Math.max(0, Math.min(100, score));
}

const row = {
  id: j.lead_id,
  lead_id: j.lead_id,
  estado,
  resultado,
  score,
  call_id: j.call_id,
  ended_reason: ended,
  duracion_seg: j.duracion_seg,
  conversacion_id: j.call_id,
  canal: 'voz',
  inicio: j.inicio,
  fin: j.fin,
  resumen: j.resumen,
  transcripcion_ref: j.grabacion_url
};

for (const k of ['nombre', 'empresa', 'sector', 'tamano', 'telefono', 'email', 'problema', 'procesos_manuales', 'quiere_automatizar', 'urgencia', 'interes', 'objecion', 'proximo_paso', 'fecha_cita', 'grabacion_url']) {
  if (j[k] !== undefined && j[k] !== null && j[k] !== '') row[k] = j[k];
}
if (j.decisor === true) row.decisor = 'si';
if (j.decisor === false) row.decisor = 'no';
if (next) row.fecha_proximo_intento = next;
if (resultado === 'cita') row.cita_id = 'CIT-' + j.call_id;

return [{ json: { ...row, _tg_resultado: resultado, _tg_score: score } }];
